// Strip precompressed duplicates and source maps from dist/ before Capacitor copies
// it into the APK assets (§4.8): the WebView local server never content-negotiates
// .gz/.br (dead weight, ~2-3x payload) and .map files would ship readable source.
// dist/ is regenerated by every `npm run build`, so deleting here is safe.
import { readdirSync, rmSync, statSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const dist = join(dirname(fileURLToPath(import.meta.url)), '..', 'dist')
const exts = ['.gz', '.br', '.map']
let removed = 0

const walk = (dir) => {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name)
    if (statSync(p).isDirectory()) walk(p)
    else if (exts.some((e) => name.endsWith(e))) {
      rmSync(p)
      removed++
    }
  }
}

walk(dist)
console.log(`[cap] dist에서 .gz/.br/.map ${removed}개 제거`)
